 const groups=()=>objs.map(o=>{const cs=camps.filter(c=>c.obj===o);const inv=cs.reduce((a,c)=>a+(N(c.investimento)||0),0);const res=cs.map(c=>N(c.resultados)).filter(x=>x!==null);const r=res.length?res.reduce((a,b)=>a+b,0):null;const tp=mode(cs.map(c=>c.tipo))||"resultados";const pm=cs.some(c=>c.porMil);return {o,cs,inv,res:r,tipo:tp,porMil:pm,cpr:r?inv/r*(pm?1000:1):null};});
 const CLICK=["trafego","vendas","leads","mensagens","app"];
