 /* weekday averages */
 let wk=null,wkBest=null,wkAvg=null;
 if(dk&&hasDates){const acc=Array.from({length:7},()=>({s:0,n:0}));serie.forEach((p,i)=>{const v=N(p[dk]);if(v===null)return;const w=sDates[i].getDay();acc[w].s+=v;acc[w].n++;});
  const rows=[1,2,3,4,5,6,0].map(w=>({w,l:WD[w],s:WDs[w],v:acc[w].n?acc[w].s/acc[w].n:null,n:acc[w].n}));const okr=rows.filter(r=>r.v!==null);
  if(okr.length>=5){wk=rows;wkBest=okr.reduce((b,r)=>r.v>b.v?r:b);wkAvg=okr.reduce((a,r)=>a+r.v,0)/okr.length;}}
 const calSpan=hasDates?Math.round((sDates[sDates.length-1]-sDates[0])/864e5)+1:0;
 const calOk=!!dk&&hasDates&&calSpan<=100;
 const calWeeks=calOk?Math.ceil(((sDates[0].getDay()+6)%7+calSpan)/7):0;

 /* pace: share of the period total reached day after day */
 const cumK=dk==="resultados"?"resultados":cnt("impressoes")>=3?"impressoes":null;
 let cum=null;
 if(cumK&&hasInvD&&serie.length>=5){const tot=k=>serie.reduce((a,p)=>a+(N(p[k])||0),0);const ti=tot("investimento"),tr=tot(cumK);
  if(ti>0&&tr>0){let ai=0,ar=0;cum={inv:[],res:[],h:Math.floor((serie.length-1)/2)};serie.forEach(p=>{ai+=N(p.investimento)||0;ar+=N(p[cumK])||0;cum.inv.push(+(ai/ti*100).toFixed(2));cum.res.push(+(ar/tr*100).toFixed(2));});}}
 const cumLabel=cumK==="resultados"?cap(tipoAll):"Exibições";

 /* cost per result, day by day */
