 if(N(MT.resultados)>0&&!mixedAll&&N(T.resultados)!==null)metas.push({k:"m-res",t:`Meta de ${tipoAll}`,v:T.resultados/MT.resultados*100,center:share(T.resultados/MT.resultados*100),sub:"da meta",det:`${int(T.resultados)} de ${int(MT.resultados)}`,good:T.resultados>=MT.resultados});
 if(N(MT.cpr)>0&&!mixedAll&&cprNow!==null)metas.push({k:"m-cpr",t:porMilAll?"Custo por mil pessoas":"Custo por resultado",v:cprNow/MT.cpr*100,center:money(cprNow),sub:porMilAll?"a cada mil pessoas":"cada",det:cprNow<=MT.cpr?`${share((1-cprNow/MT.cpr)*100)} abaixo do limite de ${money(MT.cpr)}`:`${share((cprNow/MT.cpr-1)*100)} acima do limite de ${money(MT.cpr)}`,good:cprNow<=MT.cpr,cost:true});
 if(N(MT.investimento)>0&&N(T.investimento)!==null)metas.push({k:"m-inv",t:"Verba do período",v:T.investimento/MT.investimento*100,center:share(T.investimento/MT.investimento*100),sub:"da verba usada",det:`${money(T.investimento)} de ${money(MT.investimento)}`,good:null});

 /* platforms (Instagram, Facebook...) from the placements */
