 const plats=(()=>{const m=new Map();pos.forEach(p=>{const l=platOf(p.nome);if(!m.has(l))m.set(l,{l,c:PLATS[l],v:0,items:[]});const g=m.get(l);g.v+=Number(p.valor);g.items.push({n:placeShort(p.nome),full:p.nome,v:Number(p.valor)});});
  return [...m.values()].map(g=>({...g,items:g.items.sort((a,b)=>b.v-a.v)})).sort((a,b)=>b.v-a.v);})();
 const platKnown=plats.filter(p=>p.l!=="Outros");
 const showPlat=platKnown.length>=2&&posSum>0&&platKnown.reduce((a,p)=>a+p.v,0)>=posSum*.7;

 /* each campaign's strengths, scored against the others */
 let radar=null;
 {const rc=camps.filter(c=>N(c.investimento)>0).sort((a,b)=>b.investimento-a.investimento).slice(0,6);
  if(rc.length>=2){const cpmOf=c=>div(c.investimento,c.impressoes,1000);
   const IN=(mixedAll?[]:[["Volume",c=>N(c.resultados),1],["Economia",c=>N(c.custo_por_resultado),-1]]).concat([["Interesse",c=>N(c.ctr),1],["Alcance",c=>N(c.alcance),1],["Clique barato",c=>N(c.cpc),-1]]).concat(mixedAll?[["Exibição barata",cpmOf,-1]]:[]);
   const ind=IN.filter(([,g])=>rc.every(c=>N(g(c))>0));
   if(ind.length>=3){const sc=rc.map(c=>ind.map(([,g,b])=>{const vs=rc.map(g),v=g(c);return b>0?v/Math.max(...vs)*100:Math.min(...vs)/v*100;}));
    const top=sc.map(r=>r.reduce((bi,v,j)=>v>r[bi]?j:bi,0)),strong=sc.map(r=>r.filter(v=>v>=90).length);radar={rc,ind,sc,top,strong};}}}

 /* map of Brazil, when the regions are Brazilian states */
