 const nav=!STATIC&&secs.length>2?`<nav class="d-nav" aria-label="Seções do relatório"><span>Neste relatório</span>${secs.map(x=>`<button type="button" data-go="${x.id}">${esc(x.nav)}</button>`).join("")}</nav>`:"";
 root.innerHTML=`<div class="dash v-${VER}" style="--brand:${brand};--b16:${rgba(brand,.16)};--b22:${rgba(brand,.22)};--b26:${rgba(brand,.26)};--b40:${rgba(brand,.4)}">
  <header class="d-top"><div class="d-client">${logoC}<div class="d-cname"><span class="ey">Relatório de resultados · Meta Ads</span><h2>${esc(client.name)}</h2><span class="per">${esc(rep.periodo||"")}</span></div></div><div class="d-agency">${VER==="eternal"?`<span class="vtag">Versão interna ETERNAL · não enviar ao cliente</span>`:""}<span class="by">Preparado por</span>${logoA}<span class="live">Atualizado em ${esc(made)}</span></div></header>
  ${VER==="eternal"&&(rep.faltando||[]).length?`<div class="miss"><b>Gerado com dados faltando</b><span>${rep.faltando.map(esc).join(" · ")}</span></div>`:""}
  ${nav}
  ${PICK&&AC.length>1?`<nav class="slicer" aria-label="Filtrar campanhas">${ACobjs.length>1?`<span class="lbl">Objetivos</span>${ACobjs.map(o=>`<button class="chip" type="button" data-pobj="${o}" aria-pressed="${String(SELN.length>0&&AC.filter(c=>c.obj===o).every(c=>SELN.includes(c.nome))&&SELN.length===AC.filter(c=>c.obj===o).length)}"><i style="background:${OBJ[o].c}"></i><span>${esc(OBJ[o].l)}</span></button>`).join("")}<span class="sep"></span>`:""}<span class="lbl">Campanhas</span><button class="chip" type="button" data-pall aria-pressed="${!SELN.length}"><span>Todas</span></button>${AC.map(c=>`<button class="chip" type="button" data-pick="${c.i}" aria-pressed="${SELN.includes(c.nome)}" title="${esc(c.nome)}"><i style="background:${c.color}"></i><span>${esc(c.nome)}</span></button>`).join("")}<span class="fnote">${SELN.length?`Mostrando ${SELN.length} de ${AC.length} campanhas · o PDF e o interativo saem só com elas`:"Mostrando todas as campanhas"}</span></nav>`:""}
  ${!PICK&&camps.length>1&&!STATIC?`<nav class="slicer" aria-label="Filtrar campanhas">${objChips}<span class="lbl">Campanhas</span><button class="chip" type="button" data-all aria-pressed="true"><span>Todas</span></button>${camps.map(c=>`<button class="chip" type="button" data-sel="${c.i}" aria-pressed="false" title="${esc(c.nome)}"><i style="background:${c.color}"></i><span>${esc(c.nome)}</span></button>`).join("")}<span class="fnote" data-fnote></span></nav>`:""}
  ${secs.map((x,i)=>`<section class="sec" data-sec="${x.id}"><div class="sec-h"><span class="n">${String(i+1).padStart(2,"0")}</span><h2>${esc(x.t)}</h2>${x.s?`<p>${esc(x.s)}</p>`:""}</div>${x.body}</section>`).join("")}
  <footer class="d-foot"><span>Preparado por ${esc(agency.name||"ETERNAL")} para ${esc(client.name)}${/eternal/i.test(agency.name||"")?" · Construindo sua presença no digital":""}</span><span>Fonte: Gerenciador de Anúncios da Meta</span></footer></div>`;
 const Q=s=>root.querySelector(s);

 function mk(name,opt){const el=Q(`[data-ch="${name}"]`);if(!el)return null;if(!EC){el.classList.add("nochart");el.textContent="Gráfico indisponível neste navegador.";return null;}
  let ch=null;try{ch=EC.init(el,null,{renderer:P.renderer||"svg",devicePixelRatio:P.dpr||undefined});ch.setOption({...ANIM,tooltip:TT,...opt});charts.push(ch);return ch;}
  catch(e){try{if(ch)ch.dispose();}catch(_){}if(window.console)console.error("Gráfico "+name,e);el.classList.add("nochart");el.textContent="Não foi possível desenhar este gráfico.";return null;}}

 /* ---------- KPIs (react to the campaign filter) ---------- */
 const KM={investimento:{l:"Investimento",f:"money",b:0,c:"#38BDF8"},resultados:{l:"Resultados",f:"int",b:1},custo_por_resultado:{l:"Custo por resultado",f:"money",b:-1,c:"#F59E0B"},
  alcance:{l:"Pessoas alcançadas",f:"int",b:1,c:"#A78BFA"},impressoes:{l:"Impressões",f:"int",b:1,c:"#818CF8"},frequencia:{l:"Frequência",f:"dec",b:0,c:"#94A3B8"},cpm:{l:"CPM",f:"money",b:-1,c:"#FBBF24"},
  cliques:{l:"Cliques",f:"int",b:1,c:"#F472B6"},ctr:{l:"CTR",f:"pct",b:1,c:"#34D399"},cpc:{l:"CPC",f:"money",b:-1,c:"#FB923C"}};
 const KG=[{t:"Investimento e resultado",s:"Quanto foi investido e o que isso trouxe.",c:brand,m:["investimento","resultados","custo_por_resultado"]},
  {t:"Visibilidade",s:"Quantas pessoas viram a marca e quantas vezes.",c:"#A78BFA",m:["alcance","impressoes","frequencia","cpm"]},
  {t:"Interesse",s:"Quantas pessoas pararam para saber mais.",c:"#F472B6",m:["cliques","ctr","cpc"]}];
 const kx=(k,tipo,pm,t)=>({investimento:"Valor pago à Meta pelos anúncios.",resultados:`Total de ${tipo}.`,custo_por_resultado:pm?"Custo para alcançar mil pessoas.":"Investimento dividido pelos resultados.",
  alcance:"Pessoas diferentes que viram o anúncio.",impressoes:"Vezes que o anúncio apareceu na tela.",frequencia:"Vezes que cada pessoa viu, em média.",cpm:"Custo para aparecer mil vezes.",
  cliques:"Toques no anúncio para saber mais.",ctr:N(t.ctr)!==null?`${dec1(t.ctr)} cliques a cada 100 exibições.`:"",cpc:"Custo médio de cada clique."}[k]||"");
 function drawTop(){
  const t=cur(),h=Q("[data-hero]"),vs=vis(),mx=camps.length?visMixed():false;
  const tipo=isAll()?tipoAll:(mode(vs.map(c=>c.tipo))||tipoAll);
  const pm=isAll()?porMilAll:vs.some(c=>c.porMil);
  let dl="";if(isAll()&&!mx&&PT&&N(PT.resultados)&&N(t.resultados)!==null){const ch=(t.resultados-PT.resultados)/PT.resultados*100;dl=`<span class="dl ${Math.abs(ch)<.5?"neu":ch>0?"good":"bad"}">${ch>0?"▲":ch<0?"▼":"="} ${Math.abs(ch).toLocaleString("pt-BR",{maximumFractionDigits:1})}% vs ${esc(prev.periodo||"período anterior")}</span>`;}
  let big,sub;
  if(!mx&&N(t.resultados)!==null){big=`<div class="big">${int(t.resultados)}<small>${esc(tipo)}</small></div>`;
   sub=[N(t.custo_por_resultado)!==null?`<b>${money(pm?div(t.investimento,t.resultados,1000)??t.custo_por_resultado:t.custo_por_resultado)}</b> ${pm?"a cada mil pessoas":"cada"}`:"",N(t.investimento)!==null?`<b>${money(t.investimento)}</b> investidos`:""];
  }else{big=`<div class="big">${compact(t.alcance??t.impressoes)}<small>${N(t.alcance)!==null?"pessoas alcançadas":"exibições"}</small></div>`;
   sub=[N(t.investimento)!==null?`<b>${money(t.investimento)}</b> investidos`:"",camps.length?`<b>${vs.length}</b> ${vs.length===1?"campanha":"campanhas"}`:""];}
  const spk=isAll()&&dk?bigSpark(serie.map(p=>p[dk]),brand):"";
  h.innerHTML=`<div class="k">${isAll()?"Resultado do período":"Resultado das campanhas selecionadas"}</div>${big}<div class="sub">${sub.filter(Boolean).join(" · ")}</div>${dl}${spk}`;
  const ob=Q("[data-objs]");if(ob){const gs=groups(),tot=gs.reduce((a,g)=>a+g.inv,0)||1;
   ob.innerHTML=gs.map(g=>{const act=g.cs.some(on);return `<button class="ocard${act?"":" dim"}" type="button" data-obj="${g.o}" style="--oc:${OBJ[g.o].c};--oc18:${rgba(OBJ[g.o].c,.18)}"><span class="ol">${esc(OBJ[g.o].l)}</span><span class="ov">${g.res!==null?compact(g.res):"—"}</span><span class="ot">${esc(g.tipo)}</span><span class="oc">${g.cpr!==null?`${money(g.cpr)} ${g.porMil?"a cada mil pessoas":"cada"}`:"&nbsp;"}</span><span class="ob"><i style="width:${(g.inv/tot*100).toFixed(1)}%"></i></span><span class="oi">${money(g.inv)} · ${share(g.inv/tot*100)} da verba</span></button>`;}).join("");}
  const sp={investimento:serie.map(p=>p.investimento),resultados:mixedAll?null:serie.map(p=>p.resultados),alcance:serie.map(p=>p.alcance),impressoes:serie.map(p=>p.impressoes)};
  const kcard=m=>{const M=KM[m];const col=M.c||brand;let v=t[m];if(m==="custo_por_resultado"&&pm)v=div(t.investimento,t.resultados,1000)??v;
   let dd="",cls="";const shr=!isAll()&&N(T[m])&&SHARE.includes(m)&&!(m==="resultados"&&mixedAll);
   if(isAll()&&PT&&N(PT[m])){const ch=(t[m]-PT[m])/PT[m]*100;cls=M.b===0||Math.abs(ch)<.5?"":((ch>0)===(M.b>0)?"good":"bad");dd=`${ch>0?"▲":ch<0?"▼":"="} ${Math.abs(ch).toLocaleString("pt-BR",{maximumFractionDigits:1})}% vs anterior`;}
   else if(shr)dd=`${share(t[m]/T[m]*100)} do total`;
   else if(isAll()&&days&&m==="investimento"&&N(t.investimento))dd=`≈ ${money(t.investimento/days)}/dia`;
   else if(isAll()&&days&&m==="resultados"&&N(t.resultados)&&!pm)dd=`≈ ${dec1(t.resultados/days)}/dia`;
   const vv=isAll()&&sp[m]?spark(sp[m],col):(shr?`<span class="mb"><i style="width:${Math.min(100,t[m]/T[m]*100).toFixed(1)}%"></i></span>`:"");
   const lbl=m==="resultados"?cap(tipo):m==="custo_por_resultado"?(pm?"Custo por mil pessoas":"Custo por resultado"):M.l;
   return `<div class="kpi${STATIC?"":" kd"}" style="--kc:${col}"${STATIC?"":` data-drill="${m}" role="button" tabindex="0" aria-label="${esc(lbl)}: ver de onde vem"`}><span class="l">${esc(lbl)}</span><span class="v">${F[M.f](v)}</span><span class="x">${esc(kx(m,tipo,pm,t))}</span><div class="foot"><span class="d ${cls}">${dd||"&nbsp;"}</span>${vv}</div></div>`;};
  Q("[data-kpis]").innerHTML=KG.map((g0,gi)=>{const g=gi===0&&mx?{...g0,t:"Investimento",s:"Quanto foi investido. Os resultados de cada objetivo estão no resumo acima."}:g0;const ms=g.m.filter(m=>N(t[m])!==null&&!((m==="resultados"||m==="custo_por_resultado")&&mx)&&!(m==="alcance"&&!mx&&t.alcance===t.resultados));
   return ms.length?`<div class="kg"><div class="kg-h" style="--gc:${g.c}"><b>${esc(g.t)}</b><span>${esc(g.s)}</span></div><div class="kpis">${ms.map(kcard).join("")}</div></div>`:"";}).join("");
  const fn=Q("[data-fnote]");if(fn)fn.textContent=isAll()?"Mostrando todas as campanhas":`Mostrando ${sel.size} de ${camps.length} campanhas`;
  root.querySelectorAll(".chip[data-sel]").forEach(b=>b.setAttribute("aria-pressed",String(sel.has(+b.dataset.sel))));
  root.querySelectorAll(".chip[data-obj]").forEach(b=>{const cs=camps.filter(c=>c.obj===b.dataset.obj);b.setAttribute("aria-pressed",String(!isAll()&&cs.every(c=>sel.has(c.i))&&sel.size===cs.length));});
  const all=Q("[data-all]");if(all)all.setAttribute("aria-pressed",String(isAll()));
 }

