 const hbars=(name,items,color,fmtV)=>{const tot=items.reduce((a,x)=>a+x.v,0)||1;const its=items.slice().sort((a,b)=>a.v-b.v);
  mk(name,{grid:{left:8,right:70,top:6,bottom:6,containLabel:true},tooltip:{...TT,formatter:p=>{const x=its[p.dataIndex];return `<b>${esc(x.n)}</b><br>${fmtV(x.v)} · ${share(x.v/tot*100)}`;}},xAxis:{type:"value",show:false},
   yAxis:{type:"category",data:its.map(x=>trunc(x.n,26)),...AX,axisLine:{show:false},axisLabel:{...AX.axisLabel,color:C.ink,fontSize:12}},
   series:[{type:"bar",barWidth:16,data:its.map((x,i)=>({value:x.v,itemStyle:{color:i===its.length-1?color:rgba(color,.55),borderRadius:[0,5,5,0]}})),label:{show:true,position:"right",color:C.ink,fontSize:11.5,fontWeight:600,formatter:p=>share(its[p.dataIndex].v/tot*100)}}]});};
 if(pos.length){let items=pos.map(p=>({n:p.nome,v:Number(p.valor)})).sort((a,b)=>b.v-a.v);if(items.length>8){const r=items.slice(7).reduce((a,x)=>a+x.v,0);items=items.slice(0,7).concat([{n:"Outros",v:r}]);}hbars("pos",items,"#38BDF8",dec);}
 if(reg.length){hbars("reg",reg.map(r=>({n:r.nome,v:Number(r.valor)})).sort((a,b)=>b.v-a.v).slice(0,10),mapD?brand:"#A78BFA",dec);}

